            if (other.nodes_.size() <= nodes_.capacity()) {
                if constexpr (TrackIds) {
                    auto next_ids = other.ids_;
                    nodes_ = other.nodes_;
                    ids_ = std::move(next_ids);
                } else nodes_ = other.nodes_;
                root_ = other.root_;
                free_ = other.free_;
                random_ = other.random_;
